CREATE OR REPLACE FUNCTION "Coach".sync_learner_absence_counts_from_details()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
            BEGIN
                IF TG_OP IN ('<literal redacted>', '<literal redacted>') THEN
                    PERFORM "Coach".refresh_learner_absence_counts(OLD.learner_id, OLD.learner_email);
                END IF;

                IF TG_OP IN ('<literal redacted>', '<literal redacted>') THEN
                    PERFORM "Coach".refresh_learner_absence_counts(NEW.learner_id, NEW.learner_email);
                    RETURN NEW;
                END IF;

                RETURN OLD;
            END;
            $function$

CREATE OR REPLACE FUNCTION "Learner".guard_finalized_journal_month()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
        DECLARE
            old_aptem_id bigint;
            old_month text;
            new_aptem_id bigint;
            new_month text;
            scope record;
            latest_event text;
        BEGIN
            IF TG_TABLE_NAME = '<literal redacted>' THEN
                IF TG_OP <> '<literal redacted>' THEN
                    SELECT aptem_id, month INTO old_aptem_id, old_month
                    FROM "Learner"."learner_journal_rows"
                    WHERE id = OLD.manual_activity_id;
                    old_aptem_id := COALESCE(old_aptem_id, OLD.aptem_id);
                    old_month := COALESCE(old_month, OLD.month);
                END IF;
                IF TG_OP <> '<literal redacted>' THEN
                    SELECT aptem_id, month INTO new_aptem_id, new_month
                    FROM "Learner"."learner_journal_rows"
                    WHERE id = NEW.manual_activity_id;
                    new_aptem_id := COALESCE(new_aptem_id, NEW.aptem_id);
                    new_month := COALESCE(new_month, NEW.month);
                END IF;
            ELSE
                IF TG_OP <> '<literal redacted>' THEN
                    old_aptem_id := OLD.aptem_id;
                    old_month := OLD.month;
                END IF;
                IF TG_OP <> '<literal redacted>' THEN
                    new_aptem_id := NEW.aptem_id;
                    new_month := NEW.month;
                END IF;
            END IF;

            FOR scope IN
                SELECT DISTINCT aptem_id, report_month
                FROM (
                    VALUES (old_aptem_id, old_month), (new_aptem_id, new_month)
                ) AS scopes(aptem_id, report_month)
                WHERE aptem_id IS NOT NULL AND report_month IS NOT NULL
                ORDER BY aptem_id, report_month
            LOOP
                PERFORM pg_advisory_xact_lock(hashtext(
                    '<literal redacted>' || scope.aptem_id::text
                    || '<literal redacted>' || scope.report_month
                ));
                SELECT event_type INTO latest_event
                FROM "Learner"."manual_month_finalization_events"
                WHERE aptem_id = scope.aptem_id
                  AND report_month = scope.report_month
                ORDER BY id DESC
                LIMIT 1;
                IF latest_event = '<literal redacted>' THEN
                    RAISE EXCEPTION USING
                        ERRCODE = '<literal redacted>',
                        MESSAGE = '<literal redacted>'
                            || scope.aptem_id::text || '<literal redacted>' || scope.report_month;
                END IF;
                latest_event := NULL;
            END LOOP;
            IF TG_OP = '<literal redacted>' THEN
                RETURN OLD;
            END IF;
            RETURN NEW;
        END
        $function$

CREATE OR REPLACE FUNCTION "Learner".link_journal_kbc_progress()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    owner_id bigint;
    existing_deleted_at timestamptz;
BEGIN
    IF NEW.progress_id IS NOT NULL OR coalesce(NEW.source_ref, '<literal redacted>') NOT LIKE '<literal redacted>' THEN
        RETURN NEW;
    END IF;
    SELECT id INTO owner_id FROM "Learner".learners WHERE aptem_id=NEW.aptem_id;
    IF owner_id IS NULL THEN RETURN NEW; END IF;
    PERFORM pg_advisory_xact_lock(hashtext('<literal redacted>'), owner_id::integer);
    SELECT p.id, p.deleted_at INTO NEW.progress_id, existing_deleted_at
    FROM "Learner".learner_progress_entries p
    WHERE p.learner_id=owner_id AND (
        p.kbc_attendance_key=substring(NEW.source_ref FROM 5) OR
        p.source_payload->>'<literal redacted>'=NEW.source_ref)
    ORDER BY (p.deleted_at IS NULL) DESC, p.id LIMIT 1;
    IF NEW.progress_id IS NOT NULL THEN
        NEW.canonical_learner_id := owner_id;
        NEW.deleted_at := existing_deleted_at;
    END IF;
    RETURN NEW;
END
$function$

CREATE OR REPLACE FUNCTION "Learner".link_progress_kbc_attendance()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    owner_aptem_id bigint;
    candidate_key text;
BEGIN
    IF NEW.kbc_attendance_key IS NULL AND
       coalesce(NEW.source_payload->>'<literal redacted>', '<literal redacted>') NOT LIKE '<literal redacted>'
    THEN
        RETURN NEW;
    END IF;
    SELECT aptem_id INTO owner_aptem_id FROM "Learner".learners
    WHERE id = NEW.learner_id;
    IF NEW.kbc_attendance_key IS NOT NULL THEN
        IF NOT EXISTS (SELECT 1 FROM "Learner".source_lms_attendance
            WHERE source_key = NEW.kbc_attendance_key AND aptem_id = owner_aptem_id)
        THEN
            RAISE EXCEPTION '<literal redacted>'
                USING ERRCODE = '<literal redacted>';
        END IF;
    ELSIF NEW.source_payload->>'<literal redacted>' LIKE '<literal redacted>' THEN
        candidate_key := substring(NEW.source_payload->>'<literal redacted>' FROM 5);
        SELECT source_key INTO NEW.kbc_attendance_key
        FROM "Learner".source_lms_attendance
        WHERE source_key = candidate_key AND aptem_id = owner_aptem_id;
    END IF;
    RETURN NEW;
END
$function$

CREATE OR REPLACE FUNCTION "Learner".set_epa_milestone_dates()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
                DECLARE
                    parsed_end_date date;
                BEGIN
                    BEGIN
                        parsed_end_date := NULLIF(btrim(NEW."End_date"), '<literal redacted>')::date;
                    EXCEPTION
                        WHEN invalid_text_representation OR datetime_field_overflow THEN
                            parsed_end_date := NULL;
                    END;

                    IF parsed_end_date IS NULL THEN
                        NEW."Alert_notify_for_EPA" := NULL;
                        NEW."Enter_EPA" := NULL;
                        NEW."Gateway_review_date" := NULL;
                    ELSE
                        NEW."Alert_notify_for_EPA" := (parsed_end_date - INTERVAL '<literal redacted>')::date;
                        NEW."Enter_EPA" := parsed_end_date + 7;
                        NEW."Gateway_review_date" := parsed_end_date + 14;
                    END IF;
                    RETURN NEW;
                END;
                $function$

CREATE OR REPLACE FUNCTION "Learner".set_learners_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    NEW.updated_at = now();
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION "Learner".sync_normalized_learner_json()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    row_data jsonb := to_jsonb(NEW);
    learner_key bigint := NEW.id::bigint;
    item jsonb;
    nested_item jsonb;
    answer_item jsonb;
    module_row record;
    week_row record;
    component_row record;
    progress_row record;
    ksb_row record;
    question_row record;
    correct_row record;
    activity_row record;
    plan_module_key bigint;
    plan_week_key bigint;
    progress_key bigint;
    quiz_answer_key bigint;
BEGIN
    IF NOT EXISTS (SELECT 1 FROM "Learner".learners WHERE id = learner_key) THEN
        RETURN NEW;
    END IF;

    DELETE FROM "Learner".learner_ksbs WHERE learner_id = learner_key;
    DELETE FROM "Learner".learner_training_plan_modules WHERE learner_id = learner_key;
    DELETE FROM "Learner".learner_progress_entries WHERE learner_id = learner_key;
    DELETE FROM "Learner".learner_activity_events WHERE learner_id = learner_key;

    FOR ksb_row IN
        SELECT value, ordinality
        FROM jsonb_array_elements("Learner".jsonb_array_or_empty(row_data -> '<literal redacted>'))
             WITH ORDINALITY AS entries(value, ordinality)
    LOOP
        item := ksb_row.value;
        INSERT INTO "Learner".learner_ksbs
            (learner_id, position, code, number, ksb_type, description)
        VALUES
            (learner_key, ksb_row.ordinality::integer,
             coalesce(item ->> '<literal redacted>', '<literal redacted>'), coalesce(item ->> '<literal redacted>', '<literal redacted>'),
             coalesce(item ->> '<literal redacted>', '<literal redacted>'), coalesce(item ->> '<literal redacted>', '<literal redacted>'));
    END LOOP;

    FOR module_row IN
        SELECT value, ordinality
        FROM jsonb_array_elements("Learner".jsonb_array_or_empty(row_data -> '<literal redacted>'))
             WITH ORDINALITY AS entries(value, ordinality)
    LOOP
        item := module_row.value;
        INSERT INTO "Learner".learner_training_plan_modules
            (learner_id, position, module_ref, module_title)
        VALUES
            (learner_key, module_row.ordinality::integer,
             nullif(item ->> '<literal redacted>', '<literal redacted>'), coalesce(item ->> '<literal redacted>', '<literal redacted>'))
        RETURNING id INTO plan_module_key;

        FOR week_row IN
            SELECT value, ordinality
            FROM jsonb_array_elements("Learner".jsonb_array_or_empty(item -> '<literal redacted>'))
                 WITH ORDINALITY AS entries(value, ordinality)
        LOOP
            nested_item := week_row.value;
            INSERT INTO "Learner".learner_training_plan_weeks
                (plan_module_id, position, week_ref, week_title)
            VALUES
                (plan_module_key, week_row.ordinality::integer,
                 nullif(nested_item ->> '<literal redacted>', '<literal redacted>'), coalesce(nested_item ->> '<literal redacted>', '<literal redacted>'))
            RETURNING id INTO plan_week_key;

            FOR component_row IN
                SELECT value, ordinality
                FROM jsonb_array_elements("Learner".jsonb_array_or_empty(nested_item -> '<literal redacted>'))
                     WITH ORDINALITY AS entries(value, ordinality)
            LOOP
                INSERT INTO "Learner".learner_training_plan_components
                    (plan_week_id, position, component_ref, component_title)
                VALUES
                    (plan_week_key, component_row.ordinality::integer,
                     nullif(component_row.value ->> '<literal redacted>', '<literal redacted>'),
                     coalesce(component_row.value ->> '<literal redacted>', '<literal redacted>'));
            END LOOP;
        END LOOP;
    END LOOP;

    FOR progress_row IN
        SELECT value, ordinality
        FROM jsonb_array_elements("Learner".jsonb_array_or_empty(row_data -> '<literal redacted>'))
             WITH ORDINALITY AS entries(value, ordinality)
    LOOP
        item := progress_row.value;
        INSERT INTO "Learner".learner_progress_entries (
            learner_id, entry_order, kind,
            module_ref, module_title, week_ref, week_title,
            component_ref, component_title, component_type, quiz_ref,
            attempt, grade, achieved_score, total_score, passed,
            feedback, reported_time, started_at, submitted_at, time_taken
        ) VALUES (
            learner_key, progress_row.ordinality::integer,
            coalesce(nullif(item ->> '<literal redacted>', '<literal redacted>'), '<literal redacted>'),
            nullif(item ->> '<literal redacted>', '<literal redacted>'), coalesce(item ->> '<literal redacted>', item ->> '<literal redacted>', '<literal redacted>'),
            nullif(item ->> '<literal redacted>', '<literal redacted>'), coalesce(item ->> '<literal redacted>', item ->> '<literal redacted>', '<literal redacted>'),
            nullif(item ->> '<literal redacted>', '<literal redacted>'), coalesce(item ->> '<literal redacted>', '<literal redacted>'),
            coalesce(item ->> '<literal redacted>', '<literal redacted>'), nullif(item ->> '<literal redacted>', '<literal redacted>'),
            "Learner".safe_numeric(item ->> '<literal redacted>')::integer,
            "Learner".safe_numeric(coalesce(item ->> '<literal redacted>', item ->> '<literal redacted>')),
            "Learner".safe_numeric(item ->> '<literal redacted>'),
            "Learner".safe_numeric(item ->> '<literal redacted>'),
            CASE WHEN item ? '<literal redacted>' AND jsonb_typeof(item -> '<literal redacted>') = '<literal redacted>'
                 THEN (item ->> '<literal redacted>')::boolean END,
            coalesce(item ->> '<literal redacted>', '<literal redacted>'), coalesce(item ->> '<literal redacted>', '<literal redacted>'),
            "Learner".safe_timestamptz(item ->> '<literal redacted>'),
            "Learner".safe_timestamptz(item ->> '<literal redacted>'), coalesce(item ->> '<literal redacted>', '<literal redacted>')
        ) RETURNING id INTO progress_key;

        FOR ksb_row IN
            SELECT value, ordinality
            FROM jsonb_array_elements("Learner".jsonb_array_or_empty(item -> '<literal redacted>'))
                 WITH ORDINALITY AS entries(value, ordinality)
        LOOP
            INSERT INTO "Learner".learner_progress_ksbs (progress_id, position, ksb_code)
            VALUES (progress_key, ksb_row.ordinality::integer,
                    trim(both '<literal redacted>' from ksb_row.value::text));
        END LOOP;

        FOR question_row IN
            SELECT value, ordinality
            FROM jsonb_array_elements("Learner".jsonb_array_or_empty(item -> '<literal redacted>'))
                 WITH ORDINALITY AS entries(value, ordinality)
        LOOP
            answer_item := question_row.value;
            INSERT INTO "Learner".learner_quiz_answers
                (progress_id, position, question_ref, chosen_answer_ref, is_correct, earned)
            VALUES
                (progress_key, question_row.ordinality::integer,
                 (answer_item ->> '<literal redacted>')::bigint,
                 nullif(answer_item ->> '<literal redacted>', '<literal redacted>')::bigint,
                 CASE WHEN answer_item ? '<literal redacted>' AND jsonb_typeof(answer_item -> '<literal redacted>') = '<literal redacted>'
                      THEN (answer_item ->> '<literal redacted>')::boolean END,
                 "Learner".safe_numeric(answer_item ->> '<literal redacted>'))
            RETURNING id INTO quiz_answer_key;

            FOR correct_row IN
                SELECT value, ordinality
                FROM jsonb_array_elements("Learner".jsonb_array_or_empty(answer_item -> '<literal redacted>'))
                     WITH ORDINALITY AS entries(value, ordinality)
            LOOP
                INSERT INTO "Learner".learner_quiz_correct_answers
                    (quiz_answer_id, position, answer_ref)
                VALUES
                    (quiz_answer_key, correct_row.ordinality::integer,
                     (correct_row.value #>> '<literal redacted>')::bigint);
            END LOOP;
        END LOOP;
    END LOOP;

    FOR activity_row IN
        SELECT value, ordinality
        FROM jsonb_array_elements("Learner".jsonb_array_or_empty(row_data -> '<literal redacted>'))
             WITH ORDINALITY AS entries(value, ordinality)
    LOOP
        item := activity_row.value;
        INSERT INTO "Learner".learner_activity_events (
            learner_id, event_order, kind, action, title, detail,
            component_ref, component_type, quiz_ref,
            module_title, week_title, passed, occurred_at
        ) VALUES (
            learner_key, activity_row.ordinality::integer,
            coalesce(item ->> '<literal redacted>', '<literal redacted>'), coalesce(item ->> '<literal redacted>', '<literal redacted>'),
            coalesce(item ->> '<literal redacted>', '<literal redacted>'), coalesce(item ->> '<literal redacted>', '<literal redacted>'),
            nullif(item ->> '<literal redacted>', '<literal redacted>'), coalesce(item ->> '<literal redacted>', '<literal redacted>'),
            nullif(item ->> '<literal redacted>', '<literal redacted>'), coalesce(item ->> '<literal redacted>', '<literal redacted>'),
            coalesce(item ->> '<literal redacted>', '<literal redacted>'),
            CASE WHEN item ? '<literal redacted>' AND jsonb_typeof(item -> '<literal redacted>') = '<literal redacted>'
                 THEN (item ->> '<literal redacted>')::boolean END,
            "Learner".safe_timestamptz(item ->> '<literal redacted>')
        );
    END LOOP;

    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION fetching_evidence.push_cv_funding_to_rpl()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
    DECLARE
      target_learner_id text;
    BEGIN
      IF TG_OP = '<literal redacted>' THEN
        target_learner_id := OLD.learner_id::text;
      ELSE
        target_learner_id := NEW.learner_id::text;
      END IF;

      UPDATE "fetching_evidence"."rpl_analysis_results" rpl
      SET funding = "fetching_evidence"."canonical_cv_funding"(target_learner_id)
      WHERE rpl.learner_id = target_learner_id
        AND rpl.funding IS DISTINCT FROM "fetching_evidence"."canonical_cv_funding"(target_learner_id);

      IF TG_OP = '<literal redacted>' AND OLD.learner_id IS DISTINCT FROM NEW.learner_id THEN
        UPDATE "fetching_evidence"."rpl_analysis_results" rpl
        SET funding = "fetching_evidence"."canonical_cv_funding"(OLD.learner_id::text)
        WHERE rpl.learner_id = OLD.learner_id::text
          AND rpl.funding IS DISTINCT FROM "fetching_evidence"."canonical_cv_funding"(OLD.learner_id::text);
      END IF;

      IF TG_OP = '<literal redacted>' THEN
        RETURN OLD;
      END IF;
      RETURN NEW;
    END
    $function$

CREATE OR REPLACE FUNCTION structured_manual_activities.guard_finalized_journal_month()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
        DECLARE
            old_aptem_id bigint;
            old_month text;
            new_aptem_id bigint;
            new_month text;
            scope record;
            latest_event text;
        BEGIN
            IF TG_TABLE_NAME = '<literal redacted>' THEN
                IF TG_OP <> '<literal redacted>' THEN
                    SELECT aptem_id, month INTO old_aptem_id, old_month
                    FROM "structured_manual_activities"."manual_learner_activities"
                    WHERE id = OLD.manual_activity_id;
                    old_aptem_id := COALESCE(old_aptem_id, OLD.aptem_id);
                    old_month := COALESCE(old_month, OLD.month);
                END IF;
                IF TG_OP <> '<literal redacted>' THEN
                    SELECT aptem_id, month INTO new_aptem_id, new_month
                    FROM "structured_manual_activities"."manual_learner_activities"
                    WHERE id = NEW.manual_activity_id;
                    new_aptem_id := COALESCE(new_aptem_id, NEW.aptem_id);
                    new_month := COALESCE(new_month, NEW.month);
                END IF;
            ELSE
                IF TG_OP <> '<literal redacted>' THEN
                    old_aptem_id := OLD.aptem_id;
                    old_month := OLD.month;
                END IF;
                IF TG_OP <> '<literal redacted>' THEN
                    new_aptem_id := NEW.aptem_id;
                    new_month := NEW.month;
                END IF;
            END IF;

            FOR scope IN
                SELECT DISTINCT aptem_id, report_month
                FROM (
                    VALUES (old_aptem_id, old_month), (new_aptem_id, new_month)
                ) AS scopes(aptem_id, report_month)
                WHERE aptem_id IS NOT NULL AND report_month IS NOT NULL
                ORDER BY aptem_id, report_month
            LOOP
                PERFORM pg_advisory_xact_lock(hashtext(
                    '<literal redacted>' || scope.aptem_id::text
                    || '<literal redacted>' || scope.report_month
                ));
                SELECT event_type INTO latest_event
                FROM "structured_manual_activities"."manual_month_finalization_events"
                WHERE aptem_id = scope.aptem_id
                  AND report_month = scope.report_month
                ORDER BY id DESC
                LIMIT 1;
                IF latest_event = '<literal redacted>' THEN
                    RAISE EXCEPTION USING
                        ERRCODE = '<literal redacted>',
                        MESSAGE = '<literal redacted>'
                            || scope.aptem_id::text || '<literal redacted>' || scope.report_month;
                END IF;
                latest_event := NULL;
            END LOOP;
            IF TG_OP = '<literal redacted>' THEN
                RETURN OLD;
            END IF;
            RETURN NEW;
        END
        $function$
